result = []
for source in sources:
    number = source['number']
    item = {k: source[k] for k in ['code_id', 'source_id', 'source_sha256', 'number']}
    item.update(drafts[number])
    item['status'] = 'rewrite_draft'
    required = references['requirements'][source['code_id'] + '|' + source['source_id']]
    if required:
        checks = []
        for key in required:
            target = references['targets'][key]
            target_number = target['number']
            if target['code_id'] == 'LEGITEXT000006072050':
                assessment = work_assessments[target_number] + work_context[number]
            else:
                assessment = specific_checks[number, target_number]
            checks.append(dict(target_key=key, view_sha256=target['view_sha256'], assessment=assessment))
        item['reference_checks'] = checks
    result.append(item)

assert len(result) == len(drafts) == 24
(ROOT / 'answer.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
print(f"answer.json : {len(result)} articles ; {sum(len(x.get('reference_checks', [])) for x in result)} vérifications de renvois")
